package com.daddyizz.cyberpulse.core.recommendation

import com.daddyizz.cyberpulse.core.model.Track
import java.util.UUID

/**
 * Structured model describing the listener's intent generated by AI or local rules.
 *
 * CRITICAL INVARIANT:
 * AI NEVER returns fabricated tracks or audio URLs. It solely produces structured intent
 * parameters (moods, genres, energy, eras, artists), which CyberPulse's Query Planner
 * and Candidate Ranker resolve against verified on-device, radio, and permitted catalog sources.
 */
data class PlaylistIntent(
    val title: String,
    val description: String?,
    val genres: List<String> = emptyList(),
    val moods: List<String> = emptyList(),
    val eras: List<String> = emptyList(),
    val artists: List<String> = emptyList(),
    val excludedArtists: List<String> = emptyList(),
    val energy: Int? = 50, // 1 to 100
    val tempoPreference: String? = null, // "slow", "moderate", "fast", "uptempo"
    val languagePreferences: List<String> = emptyList(),
    val targetTrackCount: Int = 15,
    val activity: String? = null
)

