    CHILL(
        displayName = "Chill",
        description = "Mellow frequencies, lo-fi textures, and ambient soundscapes",
        defaultEnergy = 30,
        defaultDiscovery = 0.4f,
        isProExclusive = false
    ),
    WORKOUT(
        displayName = "Workout",
        description = "High-octane BPM, synth pulses, and adrenaline surges",
        defaultEnergy = 90,
        defaultDiscovery = 0.5f,
        isProExclusive = false
    ),
    FOCUS(
        displayName = "Focus",
        description = "Deep electronic flow, minimal vocals, and steady cognitive momentum",
        defaultEnergy = 45,
        defaultDiscovery = 0.2f,
        isProExclusive = false
    ),
    PARTY(
        displayName = "Party",
        description = "Banger electronic anthems, dancefloor movers, and peak-hour energy",
