/**
 * Plan describing the trajectory of an active continuous Cyber DJ session.
 */
data class DjSessionPlan(
    val id: String = UUID.randomUUID().toString(),
    val mode: CyberDjMode,
    val targetEnergy: Int = mode.defaultEnergy,
    val discoveryRatio: Float = mode.defaultDiscovery,
    val primaryGenres: List<String> = emptyList(),
    val targetMoods: List<String> = emptyList(),
    val seedArtists: List<String> = emptyList(),
    val seedKeywords: List<String> = emptyList(),
    val tempoPreference: String? = null
)

/**
 * Playable source mode for playlist generation.
 */
enum class PlaylistResolutionMode {
    /**
     * Strictly Media3-direct playable tracks (Local Audio, Cyber Radio, Verified Test/Demo audio).
     * Mandatory for Android Auto, background playback, and uninterrupted listening.
     * Zero YouTube embedded or external player items allowed.
     */
    PLAYABLE_NOW,

    /**
     * Discovery mix (Phone only). May include YouTube discovery metadata alongside playable streams.
     * YouTube embedded items remain visual and are never pushed to Media3 car queue.
     */
    DISCOVERY
}

/**
 * Breakdown of sources comprising a generated playlist.
 */
data class SourceComposition(
    val localCount: Int = 0,
    val radioCount: Int = 0,
    val demoPlayableCount: Int = 0,
    val discoveryCount: Int = 0
) {
    val totalCount: Int get() = localCount + radioCount + demoPlayableCount + discoveryCount
}

/**
 * Fully resolved playlist ready for preview, playback, or saving.
 */
data class ResolvedPlaylist(
    val id: String = "ai_pl_${System.currentTimeMillis()}",
    val title: String,
    val description: String?,
    val intent: PlaylistIntent,
    val tracks: List<Track>,
    val resolutionMode: PlaylistResolutionMode,
    val sourceComposition: SourceComposition,
    val generatedAtEpoch: Long = System.currentTimeMillis()
) {
    val estimatedDurationSeconds: Long
        get() = tracks.sumOf { it.durationSeconds }

    val formattedDuration: String
        get() {
            val totalSec = estimatedDurationSeconds
            if (totalSec <= 0) return "${tracks.size} tracks"
            val hrs = totalSec / 3600
            val mins = (totalSec % 3600) / 60
            return if (hrs > 0) "${hrs} hr ${mins} min" else "${mins} min"
        }
}

/**
 * Structured AI errors with friendly user-facing explanations.
 */
sealed class AiGenerationError(val message: String, val canFallbackLocally: Boolean = true) {
    data object NoNetwork : AiGenerationError("No internet connection available. Switched to smart offline mix.", canFallbackLocally = true)
    data object RateLimited : AiGenerationError("AI generation rate limit reached. Using local smart recommendation engine.", canFallbackLocally = true)
    data object ProviderUnavailable : AiGenerationError("AI discovery service is temporarily unavailable. Generating local smart mix.", canFallbackLocally = true)
    data object MalformedResponse : AiGenerationError("AI response format was invalid. Generating local smart mix instead.", canFallbackLocally = true)
    data object NoPlayableResults : AiGenerationError("No available playable tracks matched this exact prompt. Try refining your request.", canFallbackLocally = false)
    data object SafetyRejection : AiGenerationError("Prompt could not be processed due to safety guidelines.", canFallbackLocally = false)
    data object QuotaExceeded : AiGenerationError("Daily free AI generations limit reached. Upgrade to CyberPulse Pro for expanded access.", canFallbackLocally = true)
    data class Unknown(val errorMsg: String) : AiGenerationError(errorMsg, canFallbackLocally = true)
}
